package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class Performance1128Test {
 static class Files implements Library.Source {
  final Map<String,List<NasClient.Entry>> rows=new ConcurrentHashMap<>();final AtomicInteger calls=new AtomicInteger(),active=new AtomicInteger(),maximum=new AtomicInteger();long delay;
  Files(int count,long millis){delay=millis;List<NasClient.Entry> root=new ArrayList<>();for(int i=0;i<count;i++){String path="/movies/Film"+i;NasClient.Entry dir=new NasClient.Entry("Film"+i,path,true,0);dir.modified=100;root.add(dir);NasClient.Entry video=new NasClient.Entry("Film.mkv",path+"/Film.mkv",false,1000);video.modified=100;rows.put(path,List.of(video));}rows.put("/movies",root);}
  public List<NasClient.Entry> list(String path)throws Exception{calls.incrementAndGet();int n=active.incrementAndGet();maximum.accumulateAndGet(n,Math::max);try{Thread.sleep(delay);return rows.getOrDefault(path,List.of());}finally{active.decrementAndGet();}}
  public byte[] readFile(String path,int limit){throw new AssertionError("No NFO in fixture");}
 }
 @Test public void filteredDirectoryParametersAndWritableShares(){Map<String,String> p=NasClient.directoryParameters("/downloads",0);assertEquals("dir",p.get("filetype"));assertEquals("200",p.get("limit"));assertEquals("name",p.get("sort_by"));assertFalse(p.containsKey("additional"));p=NasClient.directoryParameters("",200);assertEquals("true",p.get("onlywritable"));assertFalse(p.containsKey("additional"));}
 @Test public void directoryCacheTtlProfileAndFailure()throws Exception{AtomicLong now=new AtomicLong();AtomicInteger calls=new AtomicInteger();DirectoryCache cache=new DirectoryCache(now::get);cache.profile("fixture");DirectoryCache.Source source=(p,o)->{calls.incrementAndGet();return new NasClient.DirectoryPage(List.of(),false);};cache.get("/video",0,source);cache.get("/video",0,source);assertEquals(1,calls.get());now.set(60000);cache.get("/video",0,source);assertEquals(2,calls.get());cache.profile("other");cache.get("/video",0,source);assertEquals(3,calls.get());try{cache.get("/missing",0,(p,o)->{throw new java.io.IOException();});fail();}catch(java.io.IOException expected){}cache.get("/video",0,source);assertEquals(4,calls.get());}
 @Test public void persistentLeafSnapshotsSkipOnlyUnchangedFolders()throws Exception{
  Files f=new Files(30,0);Library first=new Library(f,null);List<Library.Card> cards=first.scan("/movies",true,n->{});assertEquals(31,f.calls.get());String persisted=first.snapshots();f.calls.set(0);
  Library second=new Library(f,null);second.previous(cards);second.snapshots(persisted);assertEquals(30,second.scan("/movies",true,n->{}).size());assertEquals(1,f.calls.get());
  f.rows.get("/movies").get(4).modified++;List<NasClient.Entry> added=new ArrayList<>(f.rows.get("/movies/Film4"));added.add(new NasClient.Entry("New.mkv","/movies/Film4/New.mkv",false,1000));f.rows.put("/movies/Film4",added);f.calls.set(0);
  Library third=new Library(f,null);third.previous(cards);third.snapshots(persisted);assertEquals(31,third.scan("/movies",true,n->{}).size());assertEquals(2,f.calls.get());
  System.out.println("BENCHMARK Android unchanged 30 folders: lists=1; added movie: lists=2");
 }
 @Test public void unknownTimeAndForceAlwaysRelist()throws Exception{Files f=new Files(3,0);Library initial=new Library(f,null);List<Library.Card> cards=initial.scan("/movies",true,n->{});for(boolean force:List.of(false,true)){f.calls.set(0);if(!force)for(NasClient.Entry e:f.rows.get("/movies"))e.modified=0;Library next=new Library(f,null);next.previous(cards);next.snapshots(initial.snapshots());next.forceMetadata(force);next.scan("/movies",true,n->{});assertEquals(4,f.calls.get());}}
 @Test public void changedGrandchildIsNotHiddenByUnchangedParent()throws Exception{Files f=new Files(1,0);NasClient.Entry dir=new NasClient.Entry("Nested","/movies/Film0/Nested",true,0);dir.modified=100;f.rows.put("/movies/Film0",List.of(dir));f.rows.put(dir.path,List.of(new NasClient.Entry("Film.mkv",dir.path+"/Film.mkv",false,1000)));Library first=new Library(f,null);List<Library.Card> cards=first.scan("/movies",true,n->{});dir.modified++;f.rows.put(dir.path,List.of(new NasClient.Entry("New.mkv",dir.path+"/New.mkv",false,1000)));f.calls.set(0);Library next=new Library(f,null);next.previous(cards);next.snapshots(first.snapshots());assertTrue(next.scan("/movies",true,n->{}).get(0).path.endsWith("New.mkv"));assertEquals(3,f.calls.get());}
 @Test public void thirtyFoldersUseAtMostThreeReadersAndKeepIdenticalOrder()throws Exception{Files serial=new Files(30,80),parallel=new Files(30,80);Library one=new Library(serial,null);one.listingParallelism(1);long start=System.nanoTime();List<Library.Card> a=one.scan("/movies",true,n->{});long before=System.nanoTime()-start;Library three=new Library(parallel,null);start=System.nanoTime();List<Library.Card> b=three.scan("/movies",true,n->{});long after=System.nanoTime()-start;assertEquals(a.stream().map(c->c.path).toList(),b.stream().map(c->c.path).toList());assertEquals(31,parallel.calls.get());assertTrue(parallel.maximum.get()<=3);assertTrue("parallel ratio="+(double)after/before,after<before*.40);System.out.println("BENCHMARK Android 30 folders: serial_ms="+before/1000000+" parallel_ms="+after/1000000+" calls="+parallel.calls.get());}
 @Test public void scanCancellationInterruptsAllListingWorkers()throws Exception{Files f=new Files(30,200);ExecutorService worker=Executors.newSingleThreadExecutor();Future<?> task=worker.submit(()->{try{new Library(f,null).scan("/movies",true,n->{});fail();}catch(InterruptedException expected){}catch(Exception error){throw new RuntimeException(error);}});Thread.sleep(250);task.cancel(true);worker.shutdown();assertTrue(worker.awaitTermination(3,TimeUnit.SECONDS));Thread.sleep(50);assertEquals(0,f.active.get());assertTrue(f.calls.get()<31);}
 @Test public void timingsContainNoRequestData(){NasTimings.record("https://secret.invalid/?sid=secret","password=secret",System.nanoTime());assertTrue(NasTimings.snapshot().containsKey("NAS request"));assertTrue(NasTimings.snapshot().keySet().stream().noneMatch(k->k.contains("secret")));}
 @Test public void unchangedLeafShowUsesPersistedListingButKeepsMetadataFlow()throws Exception{Files f=new Files(1,0);Library first=new Library(f,null);List<Library.Card> cards=first.scan("/movies",false,n->{});assertEquals(1,cards.size());f.calls.set(0);Library next=new Library(f,null);next.previous(cards);next.snapshots(first.snapshots());assertEquals(1,next.scan("/movies",false,n->{}).size());assertEquals(1,f.calls.get());}
}
